  'method4-para2' => 'Ինչպես ցանկացած առցանց ֆայլի մշակման դեպքում, վերբեռնելուց առաջ հաշվի առեք փաստաթղթի զգայունությունը: Առավել գաղտնի փաստաթղթերի համար օգտագործեք վերը նկարագրված տեղական աշխատասեղանի մեթոդները:',
  'strong-password-heading' => 'Ինչպես ընտրել ուժեղ PDF գաղտնաբառ',
  'strong-password-para1' => 'Գաղտնաբառով պաշտպանված PDF-ի անվտանգությունն ամբողջությամբ կախված է ընտրված գաղտնաբառի հզորությունից: PDF գաղտնագրումը AES-256-ով արդյունավետորեն անխախտելի է կոպիտ ուժի միջոցով, սակայն թույլ գաղտնաբառը, ինչպիսին է անունը, ամսաթիվը կամ սովորական բառը, կարող է արագ կոտրվել՝ օգտագործելով բառարանի հարձակման գործիքները, որոնք ազատ հասանելի են:',
  'strong-password-para2' => 'PDF գաղտնաբառի համար, որն ապահովում է իրական պաշտպանություն, օգտագործեք առնվազն 12 նիշ, որոնք համատեղում են մեծատառերը, փոքրատառերը, թվերը և նշանները: Խուսափեք անձնապես ճանաչելի որևէ բանից, բառարանում հայտնաբերված ցանկացած բառից և հատկապես խուսափեք այլ հաշիվներից գաղտնաբառերի վերօգտագործումից:',
  'strong-password-para3' => 'Պահպանեք PDF գաղտնաբառերը գաղտնաբառերի կառավարիչում, այլ ոչ թե էլ.փոստում, տեքստային ֆայլում կամ կպչուն գրառման մեջ: Եթե ​​մոռացել եք գաղտնաբառը, ապա վերականգնման մեխանիզմ չկա: Կոդավորումը նախագծված է այնպես, որ նույնիսկ PDF-ը ստեղծած ծառայությունը չի կարող վերականգնել մուտքն առանց բնօրինակ գաղտնաբառի:',
  'sharing-heading' => 'Անվտանգ գաղտնաբառերի փոխանակում',
  'sharing-para' => 'Պաշտպանված PDF-ի հետ նույն էլ.փոստով գաղտնաբառ ուղարկելը խախտում է պաշտպանության նպատակը: Եթե ​​էլփոստը գաղտնալսվում է, և՛ ֆայլը, և՛ բանալին ֆիքսվում են միասին: Ուղարկեք PDF-ը էլփոստով և գաղտնաբառը այլ ալիքով՝ տեքստային հաղորդագրություն, հեռախոսազանգ կամ ապահով հաղորդագրությունների հավելված: Սա ապահովում է, որ միայն մեկ ալիքի գաղտնալսումը բավարար չէ փաստաթուղթ մուտք գործելու համար:',
  'faqs-heading' => 'Հաճախակի տրվող հարցեր',
  'faq1-question' => 'Կարո՞ղ է գաղտնաբառով պաշտպանված PDF-ը կոտրվել:',
  'faq1-answer' => 'Թույլ կամ ընդհանուր գաղտնաբառով, այո: Կան գործիքներ, որոնք նախատեսված են բառարանային հարձակումների և PDF ֆայլերի դեմ գաղտնաբառի սովորական ձևերի փորձի համար: Ուժեղ պատահական գաղտնաբառով և AES-256 կոդավորումով, կոտրելը հաշվողականորեն անիրագործելի է ներկայումս հասանելի ցանկացած տեխնոլոգիայով: Գաղտնաբառի ուժը անվտանգության միակ ամենակարևոր գործոնն է:',
  'faq2-question' => 'Ի՞նչ կլինի, եթե մոռանամ PDF գաղտնաբառը:',
  'faq2-answer' => 'PDF գաղտնաբառի պաշտպանության համար ներկառուցված վերականգնման մեխանիզմ չկա: Եթե ​​դուք կորցնում եք գաղտնաբառը, տվյալների վերականգնման մասնագիտական ​​ծառայությունները կարող են փորձել կոտրել այն, բայց հաջողությունն ամբողջությամբ կախված է նրանից, թե որքան ուժեղ է եղել գաղտնաբառը: Միշտ պահեք PDF գաղտնաբառերը գաղտնաբառերի կառավարիչում, երբ դրանք ստեղծեք:',
  'faq3-question' => 'Արդյո՞ք գաղտնաբառի պաշտպանությունը խանգարում է տպագրությանը:',
  'faq3-answer' => 'Բացվող գաղտնաբառը թույլ չի տալիս ամբողջությամբ դիտել, ինչը նաև թույլ չի տալիս տպել: Թույլտվությունների գաղտնաբառը կարող է կանխել հատուկ տպագրությունը՝ միաժամանակ թույլ տալով փաստաթուղթը բացել և կարդալ: Այնուամենայնիվ, թույլտվությունների սահմանափակումները ավելի հեշտ է շրջանցել, քան գաղտնաբառի կոդավորումը բացելը, և չպետք է դրանց վրա հիմնվել բարձր անվտանգության փաստաթղթերի համար:',
  'faq4-question' => 'Արդյո՞ք PDF կոդավորումը նույնն է, ինչ փաստաթղթերի իրավունքների կառավարումը:',
  'faq4-answer' => 'Ոչ: PDF գաղտնագրումը վերահսկում է մուտքը դեպի փաստաթուղթ: Թվային իրավունքների կառավարումը կամ DRM-ն ավելի բարդ համակարգ է, որը կարող է հեռակա կարգով վերահսկել մուտքը, չեղարկել մուտքը և հետևել օգտագործմանը: PDF գաղտնագրումն ավելի պարզ, ինքնամփոփ պաշտպանություն է, որը ֆայլի ստեղծումից հետո սերվերի միացում չի պահանջում:',
  'conclusion-heading' => 'Եզրակացություն',
  'conclusion-para1' => 'PDF-ը գաղտնաբառով պաշտպանելը անվճար, արագ և արդյունավետ միջոց է զգայուն տեղեկատվություն պարունակող փաստաթղթերին բովանդակալից անվտանգություն ավելացնելու համար: Mac-ի օգտվողներն ունեն ամենահեշտ տարբերակը՝ Preview-ի ներկառուցված արտահանման կոդավորումով: Windows-ի օգտատերերը համապարփակ վերահսկողություն են ստանում LibreOffice-ի միջոցով: Երկու հարթակներն էլ աջակցում են առցանց գործիքներ PDF-ների համար, որոնք արդեն վերջնական ձևի մեջ են:',
  'conclusion-para2' => 'Ամենակարևոր տարրը ուժեղ գաղտնաբառ ընտրելն է: Փաստաթղթերի համար, որոնք պետք է ապահով կերպով համօգտագործվեն, համատեղեք PDFTools-ում կիրառվող պաշտպանությունը գաղտնաբառի ամրության և գաղտնաբառի անվտանգ առաքման վերաբերյալ վերը նշված ուղեցույցի հետ: Տես նաև PDF գաղտնագրման ստանդարտների մասին հոդվածը, որը բացատրվում է ավելի խորը հասկանալու համար, թե իրականում ինչ են նշանակում այդ պաշտպանության մակարդակները տեխնիկապես:',
);
